const t = msg.payload || {};
const ok = t.vehicleId && t.location && Array.isArray(t.location.coordinates)
  && typeof t.soc === 'number' && t.status;
msg.valid = !!ok;
return msg;

const t = msg.payload;
let alert = null;
if (t.soc < 15) alert = { type: 'low_battery', severity: 'warning' };
if (t.status === 'fault') alert = { type: 'safety_fault', severity: 'critical' };
if (!alert) return [msg, null];
msg.telemetry = t;
msg.payload = { vehicleId: t.vehicleId, ...alert, timestamp: new Date().toISOString() };
msg.topic = 'fleet/alerts/' + t.vehicleId;
return [null, msg];

// Node-RED is the only writer of alerts; the dashboard reads this collection.
const doc = { ...msg.payload, timestamp: new Date(msg.payload.timestamp), source: "node-red" };
global.get("mongo").db().collection("alerts").insertOne(doc)
  .then(() => node.done())
  .catch((e) => node.error(e, msg));
return null;

// Charge scheduler: send a low-battery vehicle to the nearest station, at most once per 10 min per
// vehicle (telemetry keeps reporting low SOC every second while it drives there).
const STATIONS = [
  { id: "stn-docklands", coordinates: [144.9460, -37.8150] },
  { id: "stn-southbank", coordinates: [144.9640, -37.8250] },
  { id: "stn-carlton", coordinates: [144.9670, -37.8000] },
  { id: "stn-richmond", coordinates: [144.9920, -37.8180] },
];
const t = msg.telemetry;
if (!(t.soc < 15) || t.status === "charging") return null;
const recent = flow.get("assigned") || {};
if (Date.now() - (recent[t.vehicleId] || 0) < 600000) return null;

const [lon, lat] = t.location.coordinates;
const rad = (d) => (d * Math.PI) / 180;
const metres = ([lon2, lat2]) => {
  const h = Math.sin(rad(lat2 - lat) / 2) ** 2 + Math.cos(rad(lat)) * Math.cos(rad(lat2)) * Math.sin(rad(lon2 - lon) / 2) ** 2;
  return 2 * 6371000 * Math.asin(Math.sqrt(h));
};
let best = null, bestM = Infinity;
for (const s of STATIONS) { const m = metres(s.coordinates); if (m < bestM) { best = s; bestM = m; } }
recent[t.vehicleId] = Date.now();
flow.set("assigned", recent);

return [
  { topic: "fleet/dispatch/" + t.vehicleId,
    payload: { command: "go_charge", stationId: best.id, location: { type: "Point", coordinates: best.coordinates } } },
  { payload: { vehicleId: t.vehicleId, stationId: best.id, distance_m: Math.round(bestM), soc: t.soc,
    assigned_at: new Date(), source: "node-red" } },
];
